  SkySceneKit.say({english="And if you want to take on a rescue job...", french="Quand tu veux effectuer une mission de secours...", german="Wenn du einen Rettungsjob übernehmen willst...", italian="E se vuoi partire per una missione di soccorso...", spanish="Lo importante es aceptar misiones de rescate..."})
  SkySceneKit.say({english="Choose the job on the 5Job List... Then, select 6Take Job. Get in the habit of doing that regularly!", french="... choisis-la dans la liste 5Missions... et confirme avec 6Accepter. N'oublie pas de le faire!", german="Wähle einen aus der 5Jobliste... Dann wähle 6Ausüben. Das solltest du regelmäßig tun!", italian="Scegli la missione dalla lista delle 5Missioni. Scegli quindi 6Vai. Ricordati di farlo regolarmente!", spanish="Ya sabes, abres la lista de 5Misiones y eliges 6Aceptar. ¡Acostúmbrate a hacerlo a menudo!"})
